def get_extended_vendor(mac_prefix: str) -> str:
    """Looks up vendor name from normalized 6-character OUI prefix."""
    return OUI_EXTENDED_DATABASE.get(mac_prefix.upper()[:8], "Enterprise Certified Hardware")
